                    conditions.append(f"{key}='{value_str}'")
                else:
                    conditions.append(f"{key}='{value}'")

            if conditions:
                query_parts.append(f"WHERE {' AND '.join(conditions)}")

        return ' '.join(query_parts)

    @staticmethod
    def insert(table, data):
        columns = ', '.join(data.keys())
        placeholders = []

        for key, value in data.items():
            if isinstance(value, str):
                # Unquote if already quoted in Python string
                value_str = value.strip("'")
                placeholders.append(f"'{value_str}'")
            else:
                placeholders.append(f"'{value}'")

        return f"INSERT INTO {table} ({columns}) VALUES ({', '.join(placeholders)})"

    @staticmethod
    def delete(table, where=None):
        query_parts = [f'DELETE FROM {table}']

        if where and isinstance(where, dict):
            conditions = []
